SELECT status, CASE WHEN monthly_fee >= 244 THEN 'high' WHEN monthly_fee >= 121 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, customer_id, COUNT(*) AS total_count, SUM(monthly_fee) AS total_monthly_fee FROM subscriptions WHERE start_date BETWEEN '2024-06-01' AND '2025-01-01' GROUP BY status, CASE WHEN monthly_fee >= 244 THEN 'high' WHEN monthly_fee >= 121 THEN 'mid' ELSE 'low' END, customer_id ORDER BY customer_id;
